{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_12",
      "quote": "Since the first report (December 2019) of the novel coronavirus disease 2019 (covid-19) caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), the number of confirmed cases and associated mortality and morbidity have increased rapidly. Pregnant women are considered a high risk group because of concerns about the effect of covid-19 on them during and after pregnancy, and on their neonates.",
      "reason": "The Introduction describes the current state of knowledge about covid-19 in pregnancy, and the callout notes that 'uncertainties remain for key outcomes that require further evidence.'"
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "callout_0",
      "quote": "our living systematic review underpinned by robust methods and continually updated at regular intervals is important for several reasons. Firstly, it addresses important research questions relevant to clinical decision making and policies. Secondly, uncertainties remain for key outcomes that require further evidence.",
      "reason": "The importance and need for the review are explicitly explained, including relevance to clinical decision making, policy, and living guidelines."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PRESENT",
      "chunk_id": "text_11",
      "quote": "This version is update 2 of the original article published on 1 September 2020 ( BMJ 2020;370:m3320), and previous updates can be found as data supplements",
      "reason": "As an update of a previous review, the manuscript identifies and cites the original publication (BMJ 2020;370:m3320)."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is a review of prevalence, clinical manifestations, risk factors, and outcomes, not of intervention effects, so no mechanism of action is required."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review is not of a complex intervention or delivery context, so a logic model is not applicable."
    }
  ],
  "confidence": 90
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The retrieved Introduction text (text_12) provides background on covid-19 in pregnancy but contains no explicit statement of the review's objective(s) or question(s). The closest evidence is in the Methods registration section (text_10), which references 'a series of research questions on covid-19 during and after pregnancy' via the PROSPERO protocol, but no explicit objective statement is reported in the retrieved evidence."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "PARTIAL",
      "chunk_id": "text_15",
      "quote": "We included studies that compared covid-19 rates, clinical manifestations (symptoms, laboratory and radiological results), risk factors, and associated mortality and morbidity between pregnant and recently pregnant and non-pregnant women of reproductive age, and those that compared maternal and perinatal outcomes in pregnant women with and without covid-19.",
      "reason": "The planned comparisons are described (pregnant/recently pregnant vs non-pregnant women; pregnant women with vs without covid-19), but they are presented as eligibility criteria in the methods rather than as a formally structured PICO statement of planned comparisons."
    }
  ],
  "confidence": 78
}

{
